function showProduct(id,el){const p=ranked.find(p=>p.id===id);if(!p)return;const t=$('#tooltip');t.innerHTML=`<button class="close" aria-label="Закрыть">×</button><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${fmt(p.orders)} заказов с товаром</p><div class="tip-stats"><div><small>Куплено</small>${fmt(p.qty)} шт.</div><div><small>Потрачено</small>${rub(p.spend)}</div><div><small>Средняя цена</small>${rub(p.spend/p.qty)}</div></div><p><strong>Цена за единицу, ₽</strong></p>${priceChart(p)}<p><span style="color:#265cff">●</span> Цена покупки <span style="color:#aab5c9;margin-left:12px">●</span> Без скидки</p><p>Средние цены совершённых покупок. Пропуски — месяцы без покупок.</p>`;t.hidden=false;const r=el.getBoundingClientRect();position(t,Math.min(r.right-420,innerWidth-460),r.top+15);t.querySelector('.close').onclick=closeTip}
function closeTip(){pinned=false;$('#tooltip').hidden=true}
$('#tooltip').onpointerenter=()=>clearTimeout(hideTimer);$('#tooltip').onpointerleave=()=>{if(!pinned)closeTip()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTip()});document.addEventListener('click',e=>{if(!e.target.closest('#tooltip')&&!e.target.closest('[data-product]'))closeTip()});
$('#category').innerHTML+=categories.map(c=>`<option>${esc(c)}</option>`).join('');$('#category').onchange=e=>setCategory(e.target.value);$('#end').onchange=e=>{if(/^\d{4}-\d{2}$/.test(e.target.value)&&e.target.value>='2023-08'&&e.target.value<='2026-08'){state.end=e.target.value;render()}else e.target.value=state.end};$('#sort').onchange=e=>{state.sort=e.target.value;renderProducts()};$('#search').oninput=e=>{state.search=e.target.value;state.all=false;renderProducts();closeTip()};$('#more').onclick=()=>{state.all=!state.all;renderProducts()};$('#reset').onclick=()=>{Object.assign(state,{end:'2026-08',category:'',sort:'spend',search:'',all:false});$('#end').value=state.end;$('#category').value='';$('#sort').value='spend';$('#search').value='';render()};$('#coverage').textContent='Даты записей в источнике: 02.09.2021–29.08.2026. Полнота граничных месяцев не подтверждена. Месяцы до начала источника не содержат наблюдений.';
